uip is connections list --all-folders --output json 2>&1 | python3 -c "
import json, sys
data = json.load(sys.stdin)
connections = data.get('Data', [])
from collections import defaultdict
groups = defaultdict(list)
for c in connections:
    if c.get('State') == 'Enabled':
        groups[c['ConnectorKey']].append({'Id': c['Id'], 'Name': c['Name']})
print('Connectors with 2+ enabled connections:')
for k, v in groups.items():
    if len(v) >= 2:
        print(f'  {k}: {len(v)} connections')
        for conn in v:
            print(f'    - {conn[\"Id\"]} ({conn[\"Name\"]})')
"

